function renderNode(node) {
  const el = document.createElement(node.type === 'a' ? 'a' : 'img');
  if (node.url && node.type === 'a') el.href = node.url;
  if (node.url && node.type === 'img') el.src = node.url;
  for (const child of node.children || []) el.appendChild(document.createTextNode(child.text || ''));
  return el;
}
